begin;
do $$ begin
 if exists(select 1 from programme_versions where change_note='st-georges-foundation-samples-20261024: before-image') then raise exception 'Samples already staged; inspect before repeating';end if;
 if exists(select 1 from programme_weeks where programme_id='9d5f562a-fa5b-44d1-a366-52e14bd3978c' and published_at is not null) then raise exception 'Draft has been published; re-audit';end if;
end $$;
insert into programme_versions(programme_week_id,snapshot,change_note)
select '8eeb46a0-7a0f-454f-83b6-50c5b10482a8',jsonb_build_object('blocks',jsonb_agg(b)),'st-georges-foundation-samples-20261024: before-image'
from session_blocks b join training_days d on d.id=b.training_day_id join programme_weeks w on w.id=d.programme_week_id where w.programme_id='9d5f562a-fa5b-44d1-a366-52e14bd3978c' and b.title='Plyometric technique stations - Coach Du review';
update session_blocks b set content='{"requirement": "Coach Du review sample", "prescriptions": [{"exerciseCode": "PLY01", "dosage": "1 x 5 landing rehearsals; hold 2 seconds", "rest": "45-60 seconds before next station", "cues": "Stand tall, drop to an athletic stance, knees follow toes. No jump needed."}, {"exerciseCode": "PLY03", "dosage": "1 x 10 small contacts", "rest": "60 seconds before next station", "cues": "Small bounces, tall body, quiet feet."}, {"exerciseCode": "PLY02", "dosage": "1 x 3 controlled jumps; reset each rep", "rest": "10-15 seconds between reps; 60-90 seconds before next station", "cues": "Comfortable distance. Land on both feet, freeze for 2 seconds. Avoid chasing distance."}, {"exerciseCode": "PLY08", "dosage": "1 x 3 small jumps; reset each rep", "rest": "10-15 seconds between reps; 60-90 seconds after station", "cues": "Small dip, jump tall, land quietly and hold for 2 seconds."}]}'::jsonb, athlete_note='Sample technique prescription; Coach Du approval required before delivery.', staff_note='Sample only: one round after ASIM, before fatigue. Reset each jump. Coach checks controlled landings and total school-sport load. Keep at least 48 hours between jumping sessions; if days are consecutive, use landing rehearsal instead of the second jump circuit. Stop for pain or loss of control. No automatic weekly increase.', admin_note='Foundation samples requested by Coach Du. Same amounts in Weeks 1-4; unpublished pending approval.' from training_days d,programme_weeks w where b.training_day_id=d.id and d.programme_week_id=w.id and w.programme_id='9d5f562a-fa5b-44d1-a366-52e14bd3978c' and w.status='draft' and w.published_at is null and d.sort_order=1 and b.title='Plyometric technique stations - Coach Du review';
update session_blocks b set content='{"requirement": "Coach Du review sample", "prescriptions": [{"exerciseCode": "PLY01", "dosage": "1 x 5 landing rehearsals; hold 2 seconds", "rest": "45-60 seconds before next station", "cues": "Stand tall, drop to an athletic stance, knees follow toes. No jump needed."}, {"exerciseCode": "PLY03", "dosage": "1 x 10 small contacts", "rest": "60 seconds before next station", "cues": "Small bounces, tall body, quiet feet."}, {"exerciseCode": "PLY06", "dosage": "1 x 6 total contacts (3 forward/back pairs)", "rest": "60-90 seconds before next station", "cues": "Tiny movements over an imaginary line. Stay tall and keep landings quiet."}, {"exerciseCode": "PLY02", "dosage": "1 x 3 controlled jumps; reset each rep", "rest": "10-15 seconds between reps; 60-90 seconds before next station", "cues": "Comfortable distance. Land on both feet, freeze for 2 seconds. Avoid chasing distance."}]}'::jsonb, athlete_note='Sample technique prescription; Coach Du approval required before delivery.', staff_note='Sample only: one round after ASIM, before fatigue. Reset each jump. Coach checks controlled landings and total school-sport load. Keep at least 48 hours between jumping sessions; if days are consecutive, use landing rehearsal instead of the second jump circuit. Stop for pain or loss of control. No automatic weekly increase.', admin_note='Foundation samples requested by Coach Du. Same amounts in Weeks 1-4; unpublished pending approval.' from training_days d,programme_weeks w where b.training_day_id=d.id and d.programme_week_id=w.id and w.programme_id='9d5f562a-fa5b-44d1-a366-52e14bd3978c' and w.status='draft' and w.published_at is null and d.sort_order=2 and b.title='Plyometric technique stations - Coach Du review';
